from app.services import users


def handle_get_user(params: dict) -> tuple[int, dict]:
    raw = params.get("id")
    if not isinstance(raw, str) or not raw.isdigit():
        return 400, {"error": "invalid id"}
    user = users.get_user(int(raw))
    if user is None:
        return 404, {"error": "not found"}
    return 200, user


def _is_valid_email(email: str) -> bool:
    """Return True when email has one @, a non-empty local part and a valid domain."""
    local, at, domain = email.partition("@")
    if not at or "@" in domain:
        return False
    if not local:
        return False
    if not domain or domain.startswith(".") or domain.endswith("."):
        return False
    return "." in domain


def handle_find_user_by_email(params: dict) -> tuple[int, dict]:
    raw = params.get("email")
    if not isinstance(raw, str):
        return 400, {"error": "invalid email"}
    email = raw.strip()
    if not _is_valid_email(email):
        return 400, {"error": "invalid email"}
    user = users.find_user_by_email(email)
    if user is None:
        return 404, {"error": "not found"}
    return 200, user
